tools.example:
s = tf('s');
G = 25 / (s^2 + 3*s + 25);
Gd = tf([1 -0.5], [1 -1.2 0.45], 0.1);     % discrete, Ts = 0.1 s
Gdelay = tf(1, [1 2 1], 'InputDelay', 0.3);
step(G, Gdelay)
legend('no delay','0.3 s delay')

A = [0 1; -25 -3];
B = [0; 25];
C = [1 0];
D = 0;
sys = ss(A, B, C, D, 'StateName', {'position','velocity'}, ...
    'InputName', 'force', 'OutputName', 'x');
step(sys)
fprintf('Poles: %s\n', mat2str(round(pole(sys), 4)'));

G = tf(25, [1 3 25]);
w = logspace(-1, 2, 200);
H = squeeze(freqresp(G, w));
meas = frd(H .* (1 + 0.02*randn(size(H))), w);
bode(G, meas)
legend('model','measured')

C = pid(2.5, 1.8, 0.35, 0.01);
G = tf(1, [1 3 2]);
T = feedback(C*G, 1);
step(T)
S = stepinfo(T);
fprintf('Overshoot %.1f%%, settling %.2f s\n', S.Overshoot, S.SettlingTime);

G = tf(1, [1 6 11 6]);
opts = pidtuneOptions('PhaseMargin', 70, 'DesignFocus', 'disturbance-rejection');
[C, info] = pidtune(G, 'PIDF', 1.5, opts);
fprintf('Kp=%.3f Ki=%.3f Kd=%.3f, PM=%.1f deg\n', C.Kp, C.Ki, C.Kd, info.PhaseMargin);
step(feedback(C*G, 1))

G = tf(1, [1 0.5 1]);
pidTuner(G, 'PIDF')
% Adjust Response Time and Transient Behavior sliders, then Export

G = tf([2 1], [1 0.4 4]);
impulse(G, 20)
[y, t] = impulse(G, 0:0.01:20);
fprintf('Energy = %.4f\n', trapz(t, y.^2));

G = ss(tf(4, [1 0.8 4]));
t = 0:0.01:20;
u = square(2*pi*0.15*t)';
[y, tOut, x] = lsim(G, u, t, [0; 0]);
plot(tOut, u, '--', tOut, y)
legend('input','output')

G = tf(1, [1 0.6 1]);
T = feedback(pid(4, 3, 0.5)*G, 1);
S = stepinfo(T, 'SettlingTimeThreshold', 0.05);
fprintf('Rise %.3f s, settle %.3f s, overshoot %.1f%%\n', ...
    S.RiseTime, S.SettlingTime, S.Overshoot);

G = tf(100, conv([1 1], [1 10 100]));
bode(G, {0.1, 1000})
grid on
[mag, ph, w] = bode(G);
magdB = 20*log10(squeeze(mag));
fprintf('Gain at 10 rad/s: %.2f dB\n', interp1(w, magdB, 10));

G = tf(1, [1 2 1]);
C = pid(5, 2, 0.1);
L = C*G;
T = feedback(L, 1);
S = feedback(1, L);
bodemag(T, S, {0.01, 100})
legend('complementary sensitivity','sensitivity')

L = tf(50, conv([1 1], [1 2 10]));
nyquist(L)
hold on, plot(-1, 0, 'r+', 'MarkerSize', 12)
[gm, pm] = margin(L);
fprintf('GM = %.2f dB, PM = %.1f deg\n', 20*log10(gm), pm);

G = tf(1, [1 3 3 1]);
C = pid(3, 1.2, 0.4);
[Gm, Pm, Wcg, Wcp] = margin(C*G);
fprintf('GM = %.2f dB at %.2f rad/s, PM = %.1f deg at %.2f rad/s\n', ...
    20*log10(Gm), Wcg, Pm, Wcp);
margin(C*G)

A = [-1 0.5; -0.5 -2]; B = eye(2); C = eye(2); D = zeros(2);
P = ss(A, B, C, D);
sigma(P, {0.01, 100})
grid on
[sv, w] = sigma(P);
fprintf('Peak gain %.3f\n', max(sv(1,:)));

G = tf(1, conv([1 0], conv([1 2], [1 5])));
rlocus(G)
sgrid(0.5, [])           % overlay zeta = 0.5 lines
axis([-8 2 -6 6])
[r, k] = rlocus(G, 0:0.5:100);

G = zpk([-3], [-1+2i, -1-2i, -8], 5);
pzmap(G)
sgrid
[p, z] = pzmap(G);
fprintf('Stable: %d\n', all(real(p) < 0));

G = tf(10, [1 4 13]);
p = pole(G)
zeta = -real(p) ./ abs(p);
fprintf('Damping ratio %.3f, wn = %.3f rad/s\n', zeta(1), abs(p(1)));

G = tf([-1 2], [1 3 2]);
[z, k] = zero(G);
fprintf('Zero at %.3f (nonminimum phase: %d)\n', z, real(z) > 0);
step(G)   % note the initial undershoot

G = tf(6, [1 2 3]);
k = dcgain(G)                 % 2
C = pid(1, 0.5, 0);
T = feedback(C*G, 1);
fprintf('Closed-loop DC gain %.4f (should be 1 with integral action)\n', dcgain(T));

G = tf(1, conv([1 0.2 1], [1 10]));
damp(G)
[wn, zeta, p] = damp(G);
[~, worst] = min(zeta);
fprintf('Least damped mode: zeta = %.3f at %.2f rad/s\n', zeta(worst), wn(worst));

G = tf(1, [1 1]);
C = pid(10, 5);
T = feedback(C*G, 1);
fprintf('Open loop BW %.3f, closed loop BW %.3f rad/s\n', ...
    bandwidth(G), bandwidth(T));

G = tf(1, [1 2 3]);
C = pid(5, 4, 0.5);
T = feedback(C*G, 1);            % closed loop
S = feedback(1, C*G);            % sensitivity
step(T), hold on, step(S)
legend('T','S')

actuator = tf(1, [0.05 1]);
plant = tf(2, [1 1 4]);
openloop = series(actuator, plant);
isequal(tf(openloop), tf(plant*actuator))
bode(openloop)

fast = tf(1, [0.1 1]);
slow = tf(3, [2 1]);
combined = parallel(fast, slow);
bodemag(fast, slow, combined, {0.01, 100})
legend('fast','slow','sum')

G = tf(1, [1 2 3], 'InputName', 'u', 'OutputName', 'y');
C = pid(4, 2, 0.3);
C.InputName = 'e'; C.OutputName = 'u';
Sum = sumblk('e = r - y');
T = connect(G, C, Sum, 'r', 'y');
step(T)

G = tf(1, [1 0.5 1]);
Ts = 0.05;
Gz1 = c2d(G, Ts, 'zoh');
opts = c2dOptions('Method', 'tustin', 'PrewarpFrequency', 1.0);
Gz2 = c2d(G, Ts, opts);
bode(G, Gz1, Gz2, {0.1, pi/Ts})
legend('continuous','zoh','tustin prewarped')

Gz = tf([0.1 0.05], [1 -1.5 0.7], 0.1);
Gc = d2c(Gz, 'tustin');
bode(Gz, Gc)
fprintf('Continuous poles: %s\n', mat2str(round(pole(Gc), 3)'));

G = tf(conv([1 2], [1 5]), conv([1 2], [1 3 10]));
order_before = order(ss(G));
Gr = minreal(G);
fprintf('Order %d -> %d\n', order_before, order(ss(Gr)));
sys = ss(blkdiag([-1 0; 0 -2]), [1; 0], [1 0], 0);
minreal(sys)

rng(0)
sys = rss(20, 1, 1);
hsv = hsvd(sys);
semilogy(hsv, 'o-'); title('Hankel singular values')
opts = balredOptions('StateProjection', 'MatchDC');
rsys = balred(sys, 6, opts);
bode(sys, rsys)
legend('full order 20','reduced order 6')

A = [0 1; -2 -3]; B = [0; 1];
Co = ctrb(A, B);
fprintf('rank = %d of %d -> controllable: %d\n', rank(Co), size(A,1), rank(Co) == size(A,1));
unco = size(A,1) - rank(Co);

A = [0 1; -2 -3]; C = [1 0];
Ob = obsv(A, C);
fprintf('Observable: %d\n', rank(Ob) == size(A,1));
L = place(A', C', [-10 -12])';   % observer gains

A = [0 1; -4 -0.4]; B = [0; 1]; C = [1 0]; D = 0;
G = eye(2); H = zeros(1,2);
plant = ss(A, [B G], C, [D H]);
Qn = diag([0.01 0.01]);
Rn = 0.05;
[kest, L, P] = kalman(plant, Qn, Rn);
fprintf('Gain L = %s\n', mat2str(round(L, 4)'));

A = [0 1; -2 -3]; B = [0; 1]; C = [1 0]; D = 0;
p = [-4+4i, -4-4i];
[K, prec] = place(A, B, p);
cl = ss(A - B*K, B, C, D);
fprintf('Achieved poles: %s (%.1f digits)\n', mat2str(round(pole(cl),4)'), prec);
step(cl)

G = tf(1, conv([1 0], [1 2 5]));
C0 = tf(10*[1 1], [1 10]);
controlSystemDesigner({'rlocus','bode'}, G, C0)
% Tune interactively, then Export the compensator
